@startuml

class Customer {
  + name : string
  + phoneNumber : string
}

class Table {
  + seatCount : int
  + isSmoking : boolean
}

class Reservation {
  + date : date
  + time : time
  + numberOfPeople : int
}

class Waiter {
  + name : string
  + yearsOfService : int
}

class Bill {
  + totalAmount : double
}

class Dish {
  + name : string
  + unitPrice : double
}

Customer "1" -- "0..*" Reservation : makes
Reservation "1" -- "1..*" Table : assignedTo
Waiter "1" -- "0..*" Reservation : manages
Waiter "1" -- "0..*" Bill : serves
Customer "1" -- "0..*" Bill : pays
Bill "1" *-- "1..*" Dish : contains

@enduml

